function memoize(fn) {
  var cache = {};
  return function (n) {
    if (!(n in cache)) {
      cache[n] = fn(n);
    }
    return cache[n];
  };
}

var fib = memoize(function (n) {
  return n <= 1 ? n : fib(n - 1) + fib(n - 2);
});

console.log(fib(30));
